cd /root/gated_mfrm_judge_bias/exp001/results && for d in *_n17; do cat "$d"/*.jsonl 2>/dev/null; done | python3 -c "
import json, sys
models_a = set()
models_b = set()
for line in sys.stdin:
    try:
        d = json.loads(line.strip())
        if 'model_a' in d: models_a.add(d['model_a'])
        if 'model_b' in d: models_b.add(d['model_b'])
    except: pass
print('=== model_a values ===')
for m in sorted(models_a): print(f'  {m}')
print(f'Total: {len(models_a)}')
print()
print('=== model_b values ===')
for m in sorted(models_b): print(f'  {m}')
print(f'Total: {len(models_b)}')
print()
all_models = models_a | models_b
print('=== All unique models (union) ===')
for m in sorted(all_models): print(f'  {m}')
print(f'Total: {len(all_models)}')
"

